mapper.select:
select count(1)
from app_user
where username = #{username}

mapper.update:
update app_user
set status = #{status}
where id = #{id}

update app_user
set nickname = #{nickname},
    email = #{email}
where id = #{id}

update app_user
set password_hash = #{passwordHash}
where id = #{id}

update app_user
set password_hash = #{passwordHash}
where email = #{email}

mapper.select:
select count(1) from app_user u left join club_member cm on cm.user_id = u.id
u.username like concat('%', #{keyword}, '%')
and cm.department_id = #{departmentId}

select u.id, u.username, u.nickname, u.email, u.status, cm.department_id, d.name as department_name, cm.joined_at, cm.status as member_status, case when dl.id is null then false else true end as department_leader, group_concat(distinct r.code order by r.code separator ',') as roles, u.created_at from app_user u left join club_member cm on cm.user_id = u.id left join department d on d.id = cm.department_id left join department_leader dl on dl.user_id = u.id and dl.department_id = cm.department_id left join user_role ur on ur.user_id = u.id left join role r on r.id = ur.role_id
u.username like concat('%', #{keyword}, '%')
and cm.department_id = #{departmentId}
group by u.id, u.username, u.nickname, u.email, u.status, cm.department_id, d.name, cm.joined_at, cm.status, dl.id, u.created_at order by u.id limit #{size} offset #{offset}
